import functools


def collect_errors(validators, data):
    errors = []
    for validator in validators:
        try:
            validator(data)
        except Exception as e:
            errors.append(e)
    return errors


def error_boundary(fn, handler):
    try:
        return fn()
    except Exception as e:
        return handler(e)


def null_safe(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        try:
            return fn(*args, **kwargs)
        except (AttributeError, TypeError):
            return None
    return wrapper
